	tree, repo, err := checkpoint.GetV2MetadataTree(ctx, FetchV2MainTreeOnly, FetchV2MainRef, openRepository)
	if err == nil {
		return tree, repo, nil
	}

	// Try checkpoint remote if configured (fetch ref, then read locally)
